CREATE TYPE "mentor_booking_status" AS ENUM ('requested', 'accepted', 'reschedule_requested', 'rejected', 'cancelled', 'completed');
CREATE TABLE "mentor_bookings" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "mentor_profile_id" UUID NOT NULL, "student_id" UUID NOT NULL, "topic" TEXT NOT NULL, "scheduled_start" TIMESTAMP(3) NOT NULL, "scheduled_end" TIMESTAMP(3) NOT NULL, "status" "mentor_booking_status" NOT NULL DEFAULT 'requested', "pending_requested_by_id" UUID NOT NULL, "cancellation_reason" TEXT, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "mentor_bookings_pkey" PRIMARY KEY ("id"), CONSTRAINT "mentor_booking_time_check" CHECK ("scheduled_start" < "scheduled_end"));
CREATE TABLE "mentor_booking_status_history" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "booking_id" UUID NOT NULL, "from_status" "mentor_booking_status", "to_status" "mentor_booking_status" NOT NULL, "changed_by_id" UUID NOT NULL, "previous_scheduled_start" TIMESTAMP(3), "previous_scheduled_end" TIMESTAMP(3), "scheduled_start" TIMESTAMP(3) NOT NULL, "scheduled_end" TIMESTAMP(3) NOT NULL, "reason" TEXT, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "mentor_booking_status_history_pkey" PRIMARY KEY ("id"));
CREATE INDEX "mentor_bookings_mentor_profile_id_status_scheduled_start_idx" ON "mentor_bookings"("mentor_profile_id", "status", "scheduled_start");
CREATE INDEX "mentor_bookings_student_id_status_scheduled_start_idx" ON "mentor_bookings"("student_id", "status", "scheduled_start");
CREATE INDEX "mentor_bookings_scheduled_start_scheduled_end_idx" ON "mentor_bookings"("scheduled_start", "scheduled_end");
CREATE INDEX "mentor_booking_status_history_booking_id_created_at_idx" ON "mentor_booking_status_history"("booking_id", "created_at");
ALTER TABLE "mentor_bookings" ADD CONSTRAINT "mentor_bookings_mentor_profile_id_fkey" FOREIGN KEY ("mentor_profile_id") REFERENCES "mentor_profiles"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "mentor_bookings" ADD CONSTRAINT "mentor_bookings_student_id_fkey" FOREIGN KEY ("student_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "mentor_bookings" ADD CONSTRAINT "mentor_bookings_pending_requested_by_id_fkey" FOREIGN KEY ("pending_requested_by_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "mentor_booking_status_history" ADD CONSTRAINT "mentor_booking_status_history_booking_id_fkey" FOREIGN KEY ("booking_id") REFERENCES "mentor_bookings"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "mentor_booking_status_history" ADD CONSTRAINT "mentor_booking_status_history_changed_by_id_fkey" FOREIGN KEY ("changed_by_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
